  1 // andesim -- multi-engine driver for the Andes simulators (QEMU, Verilator,
  2 // and future backends). One C++20 binary that selects a model (fast / cycle
  3 // / hybrid), resolves engines at runtime, and either passes through to a single
  4 // engine or orchestrates a hybrid round-trip.
  5 //
  6 // This file owns argument dispatch only: parse the CLI, route to a command.
  7 #include <cstdio>
  8 #include <cstdlib>
  9 #include <exception>
 10 #include <string>
 11 #include <string_view>
 12 
 13 #include "cli.hpp"
 14 #include "dev_mode.hpp"
 15 #include "log.hpp"
 16 
 17 namespace andes_sim {
 18 int cmd_list(const Cli& cli);
 19 int cmd_doctor(const Cli& cli);
 20 int cmd_run(const Cli& cli);
 21 int cmd_profile(const Cli& cli);
 22 }  // namespace andes_sim
 23 
 24 namespace {
 25 
 26 using andes_sim::Cli;
 27 using andes_sim::cmd_doctor;
 28 using andes_sim::cmd_list;
 29 using andes_sim::cmd_profile;
 30 using andes_sim::cmd_run;
 31 using andes_sim::is_dev_mode;
 32 
 33 // The known command names live in cli.cpp (is_subcommand): the parser needs
 34 // them for the default-command rule, so parse_cli only ever yields run/
 35 // profile/list/doctor (or "" for no args / top-level help). Developer
 36 // build/test tooling lives in scripts/, not the binary.
 37 
 38 // ---- help model: the user-facing surface rendered as a command tree --------
 39 //
 40 // `run`'s two subcommand groups -- the modes (the composition axis) ...
 41 struct ModeRow {
 42   const char* name;
 43   const char* brief;
 44 };
 45 constexpr ModeRow kRunModes[] = {
 46     {"fast", "QEMU only -- functional, full speed"},
 47     {"cycle", "one cycle-accurate engine, from reset"},
 48     {"hybrid", "QEMU fast-forwards, then vsim measures the ROI"},
 49 };
 50 
 51 // `list`'s targets. `fixtures` (internal test ELFs) is a developer target,
 52 // shown only under ANDESIM_DEV; the product lists user-facing models/engines.
 53 struct TargetRow {
 54   const char* name;
 55   const char* brief;
 56   bool dev;
 57 };
 58 constexpr TargetRow kListTargets[] = {
 59     {"models", "the modes and their engines", false},
 60     {"engines", "discovered cycle-accurate engines", false},
 61     {"fixtures", "internal test ELFs (developer target)", true},
 62 };
 63 
 64 // ... and `run`'s options. Each `flag` carries its own leading indent (the pc
 65 // boundaries nest under --trigger pc). `tag` marks a required option (and WHEN
 66 // it is required).
 67 struct OptRow {
 68   const char* flag;  // includes its own leading indent
 69   const char* tag;
 70   const char* brief;
 71 };
 72 constexpr OptRow kRunOpts[] = {
 73     {"  --mode fast|cycle|hybrid", "REQUIRED", "which mode to run"},
 74     {"  --trigger marker|pc", "REQUIRED for hybrid", "the ROI delimiter"},
 75     {"    --pc-start <sym|0x>", "REQUIRED for --trigger pc", "ROI start boundary"},
 76     {"    --pc-end <sym|0x>", "REQUIRED for --trigger pc", "ROI end boundary"},
 77     {"  --engine <id>", "", "pick an engine, e.g. vsim:ax45mpv_premium (default: the sole one)"},
 78     {"  --mem-size <spec>", "", "guest RAM, e.g. 256M / 2G (hybrid: max 2G; fast: QEMU -m; cycle: ignored)"},
 79     {"  --dry-run", "", "print the exact engine command(s) and exit, running nothing (fast/cycle/hybrid)"},
 80     {"  --print-memmap", "", "print the hybrid guest memory map and exit, running nothing (hybrid only; ELF optional)"},
 81     {"  --verify", "", "cross-check the hybrid run against a QEMU oracle"},
 82     {"  --kanata <file>", "", "write a Kanata pipeline trace of the ROI (hybrid only; open in Konata)"},
 83     {"    --objdump <file>", "", "embed that objdump -d dump's disassembly in the trace (requires --kanata)"},
 84     {"  --gdb", "", "pause at startup for a debugger (fast: QEMU stub; cycle: vsim JTAG + $ICEMAN; not hybrid)"},
 85     {"  --gdb-port <port>", "", "override the --gdb port (fast 1234, cycle 9104)"},
 86     {"  --log-level <0-6>", "", "verbosity, vsim's scale: 0=trace 1=debug 2=info 3=warn 4=error 5=critical 6=off (default 2: program output + the cycle figure)"},
 87     {"  --log-file <file>", "", "append EVERY level's messages (timestamped) to <file>; the console keeps --log-level"},
 88     {"  --step-timeout-ms <ms>", "", "hybrid per-leg spawn timeout (default 90000); raise it for a large ROI on the cycle-accurate leg"},
 89     {"  -- <args...>", "", "forward everything after -- verbatim to the engine (fast/cycle); hybrid rejects -- args, EXCEPT --runtime linux, where they are app argv"},
 90 };
 91 
 92 // A major command line at column 0: `name   brief`.
 93 void print_major(std::FILE* out, const char* name, const char* brief) {
 94   std::fprintf(out, "%-7s %s\n", name, brief);
 95 }
 96 
 97 // A subcommand/target line, indented two under its command: `  name   brief`.
 98 void print_sub(std::FILE* out, const char* name, const char* brief) {
 99   std::fprintf(out, "  %-9s %s\n", name, brief);
100 }
101 
102 // An option line: `<indent>--flag    [TAG  ]brief`, flags aligned to a column.
103 void print_opt(std::FILE* out, const OptRow& o) {
104   if (o.tag[0])
105     std::fprintf(out, "%-29s %s  %s\n", o.flag, o.tag, o.brief);
106   else
107     std::fprintf(out, "%-29s %s\n", o.flag, o.brief);
108 }
109 
110 // `run`: major line, the mode subcommands, then the option list. Shared by
111 // the top-level tree and `run --help`.
112 void print_run_block(std::FILE* out) {
113   print_major(out, "run", "run one simulation (the default: 'run' may be omitted)");
114   for (const ModeRow& m : kRunModes) print_sub(out, m.name, m.brief);
115   std::fputs("\n", out);
116   for (const OptRow& o : kRunOpts) print_opt(out, o);
117 }
118 
119 void print_list_block(std::FILE* out) {
120   print_major(out, "list", "list what is available");

